#include<bits/stdc++.h>
using namespace std;
using LL = long long;
const int N = 5;
LL a, b, sum[N][N], t[N][N];
inline LL read() {
    LL w = 0, t = 1;
    char ch = getchar();
    while(ch < '0' || ch > '9'){if(ch == '-')t = -1;ch = getchar();}
    while('0' <= ch && ch <= '9')w = w*10+(ch&15),ch = getchar();
    return w*t;
}
int main() {
    a = read(), b = read();
    for(int i = 1; i <= 2; i++)
        for(int j = 1; j <= 2; j++) {
            if(i == 1)t[i][j] = a;
            else t[i][j] = b;
            sum[i][j] = sum[i-1][j]+sum[i][j-1] - sum[i-1][j-1] + t[i][j];
        }
    printf("%lld\n", sum[2][2]-sum[2][1]);
    return 0;
}
